import type { AudioManifest, Chapter, ChapterId, Leg, NarrationClip, Puzzle, Thread, Waypoint, WaypointId } from './types';
import { CHAPTERS, CHAPTER_IDS } from './chapters';
import { LEGS } from './legs';
import { NARRATION, NARRATION_IDS, transcriptOf } from './narration';
import { PUZZLES, PUZZLE_IDS } from './puzzles';
import { WAYPOINTS, WAYPOINT_IDS } from './waypoints';
import audioManifestJson from './audio-manifest.json';

export { CHAPTERS, CHAPTER_IDS, LEGS, NARRATION, NARRATION_IDS, PUZZLES, PUZZLE_IDS, WAYPOINTS, WAYPOINT_IDS, transcriptOf };

/** Generated by scripts/tts/build_narration.py: which audio file belongs to which clip. */
export const AUDIO_MANIFEST = audioManifestJson as AudioManifest;

const chapterMap = new Map<ChapterId, Chapter>(CHAPTERS.map((c) => [c.id, c]));

export function chapterById(id: ChapterId): Chapter {
  const c = chapterMap.get(id);
  if (!c) throw new Error(`Unknown chapter ${id}`);
  return c;
}

export function puzzleById(id: string): Puzzle {
  const p = PUZZLES[id];
  if (!p) throw new Error(`Unknown puzzle ${id}`);
  return p;
}

export function waypointById(id: WaypointId): Waypoint {
  return WAYPOINTS[id];
}

export function legById(id: string | undefined): Leg | undefined {
  return id ? LEGS[id] : undefined;
}

export function clipById(id: string): NarrationClip | undefined {
  return NARRATION[id];
}

/** Every thread in chapter order, with the chapter it belongs to. */
export function allThreads(): { thread: Thread; chapter: Chapter }[] {
  return CHAPTERS.flatMap((chapter) => (chapter.thread ? [{ thread: chapter.thread, chapter }] : []));
}

export function threadById(id: string): { thread: Thread; chapter: Chapter } | undefined {
  return allThreads().find((t) => t.thread.id === id);
}

export function factById(id: string) {
  for (const chapter of CHAPTERS) {
    const fact = chapter.facts.find((f) => f.id === id);
    if (fact) return { fact, chapter };
  }
  return undefined;
}

/** The audio URL (relative to the app root) for a clip, if it was rendered. */
export function audioFileFor(clipId: string): string | undefined {
  return AUDIO_MANIFEST[clipId]?.file;
}
